      '--g-muted': resolved('--color-text-secondary', dark ? '#a7a9b0' : '#62656c'),
      '--g-border': resolved('--color-border', dark ? '#ffffff22' : '#00000024'),
      '--g-panel': resolved('--color-background-panel', resolved('--color-background-primary-soft-alpha', dark ? '#232329' : '#ffffffc0')),
      '--g-control': resolved('--color-background-primary-soft-alpha', dark ? '#ffffff14' : '#0000000d'),
      '--g-hover': resolved('--color-background-primary-ghost-hover', dark ? '#ffffff1f' : '#00000014'),
      '--g-accent': resolved('--color-text-info', dark ? '#a8c7fa' : '#0285ff'),
