      '--owg-line-rgb': dark ? '255 255 255' : '27 32 42',
      '--owg-mask-rgb': dark ? '0 0 0' : '255 255 255',
      '--owg-scene': state.source === 'solid' ? 'none' : `radial-gradient(ellipse at 18% 12%, rgb(${rgb} / ${dark ? '.48' : '.28'}), transparent 65%),radial-gradient(ellipse at 86% 88%, rgb(${rgb} / ${dark ? '.16' : '.13'}), transparent 55%)`,
