      '--owg-brightness': state.bgBrightness / 100, '--owg-bg-saturation': state.bgSaturation / 100,
      '--owg-bg-opacity': state.bgOpacity / 100, '--owg-scale': state.bgScale / 100,
      '--owg-fit': state.fit, '--owg-x': `${state.positionX}%`, '--owg-y': `${state.positionY}%`,
      '--owg-shade': state.shade / 100, '--owg-glass-blur': `${state.lowPower ? 0 : state.glassBlur}px`,
      '--owg-glass-saturation': state.glassSaturation / 100,
      '--owg-glass-filter': state.lowPower ? 'none' : `blur(${state.glassBlur}px) saturate(${state.glassSaturation / 100})`,
      '--owg-radius': `${state.radius}px`, '--owg-border-opacity': state.borderOpacity / 100,
      '--owg-message-filter': state.lowPower || !state.messageGlass ? 'none' : `blur(${state.glassBlur}px) saturate(${state.glassSaturation / 100})`,
      '--owg-assistant-padding': `${state.assistantPadding}px`, '--owg-assistant-gap': `${state.assistantGap}px`,
      '--owg-assistant-radius': `${state.assistantRadius}px`
